mariadb-m1-l4.code:
START TRANSACTION;
UPDATE learning_tasks
SET minutes = minutes + 5
WHERE id = 1 AND minutes <= 595;
-- Connector prüft betroffene Zeilen; 0 ist ein eigener fachlicher Fall.
COMMIT;
-- Bei Fehler: ROLLBACK.
-- Das ist keine Transaktion über einen externen Mail-/Zahlungsdienst.

